UPDATE businesses SET description = 'L&W Traders is an independent general store in Colorado City Centre on Caesars Drive, serving households in Colorado Park and the surrounding parts of Mitchells Plain. It stocks a broad mix of everyday household essentials and groceries, along with seasonal goods that change through the year.

Prices are kept competitive so local families can buy their regular supplies without spending more than they need to, and the store aims to keep the items people use most reliably on the shelves. As an independent, locally run business, it offers friendly, personal service, with staff who are happy to help customers find what they are looking for. Its location in the neighbourhood''s main shopping centre means residents can pick up routine supplies quickly and close to home. L&W Traders is at Colorado City Centre, Caesars Drive, Colorado Park, Mitchells Plain.', description_enriched_at = datetime('now') WHERE slug = 'lw-traders-colorado' AND description = 'L&W Traders is a general retail store inside Colorado City Centre in Colorado Park, Mitchells Plain.' AND description_enriched_at IS NULL AND length(COALESCE(description, '')) < 700
  AND owner_user_id IS NULL AND COALESCE(subscription_tier, 0) = 0 AND COALESCE(origin, '') != 'owner_submitted'
  AND status = 'published' AND closed_at IS NULL AND is_test = 0
  AND custom_blocks IS NULL AND page_html IS NULL
  AND NOT EXISTS (SELECT 1 FROM business_claims c WHERE c.business_id = businesses.id)
  AND NOT EXISTS (SELECT 1 FROM subscriptions s WHERE s.business_id = businesses.id)
  AND NOT EXISTS (SELECT 1 FROM business_photos p WHERE p.business_id = businesses.id);
-- ok-furniture-delft-mall-delft (owner)
UPDATE businesses SET description = 'OK Furniture Delft Mall is the Delft branch of the national furniture and appliance chain, trading from Shop 25 in Delft Mall at the corner of Hindle Road and Delft Main Road. It is geared towards families who want to furnish their homes well without overspending.

Inside the showroom, customers can compare lounge suites, bedroom suites and dining sets, as well as large kitchen appliances and home entertainment electronics. Seeing the furniture in person makes it easier to judge size, comfort and quality before buying. For bigger purchases, flexible credit lets households spread payments over several months, putting new furniture within reach sooner. Helpful staff guide shoppers through their options and the buying process. OK Furniture is at Shop 25, Delft Mall, Delft, Cape Town.', description_enriched_at = datetime('now') WHERE slug = 'ok-furniture-delft-mall-delft' AND description = 'OK Furniture is a furniture and homeware retailer inside Delft Mall, part of the OK Furniture chain.' AND description_enriched_at IS NULL AND length(COALESCE(description, '')) < 700
  AND owner_user_id IS NULL AND COALESCE(subscription_tier, 0) = 0 AND COALESCE(origin, '') != 'owner_submitted'
  AND status = 'published' AND closed_at IS NULL AND is_test = 0
  AND custom_blocks IS NULL AND page_html IS NULL
  AND NOT EXISTS (SELECT 1 FROM business_claims c WHERE c.business_id = businesses.id)
  AND NOT EXISTS (SELECT 1 FROM subscriptions s WHERE s.business_id = businesses.id)
